$ErrorActionPreference='Continue'
$wt='C:\Users\Xxkan\AppData\Local\Temp\mhw-main-converge-opui-a3'
if(-not (Test-Path $wt)){ throw 'integration worktree missing' }
Set-Location $wt
$pre=(git rev-parse HEAD | Out-String).Trim()
Set-Location (Join-Path $wt 'tools\agent-control')
& npm.cmd run check
$check=$LASTEXITCODE
if($check -ne 0){ throw "npm check failed exit=$check" }
& npm.cmd test
$test=$LASTEXITCODE
if($test -ne 0){ throw "npm test failed exit=$test" }
Set-Location $wt
git fetch origin
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
$current=(git rev-parse origin/main | Out-String).Trim()
$base=(git merge-base HEAD origin/main | Out-String).Trim()
if($current -ne $base){
  git merge --no-ff --no-edit origin/main
  if($LASTEXITCODE -ne 0){ $conf=@(git diff --name-only --diff-filter=U); git merge --abort | Out-Null; throw "reconcile conflict: $($conf -join ', ')" }
  Set-Location (Join-Path $wt 'tools\agent-control')
  & npm.cmd run check
  $check2=$LASTEXITCODE
  if($check2 -ne 0){ throw "post-reconcile npm check failed exit=$check2" }
  & npm.cmd test
  $test2=$LASTEXITCODE
  if($test2 -ne 0){ throw "post-reconcile npm test failed exit=$test2" }
  Set-Location $wt
}
$final=(git rev-parse HEAD | Out-String).Trim()
git push origin "HEAD:main"
if($LASTEXITCODE -ne 0){ throw 'push main failed' }
git fetch origin main | Out-Null
$remote=(git rev-parse origin/main | Out-String).Trim()
if($remote -ne $final){ throw "verification mismatch final=$final remote=$remote" }
[ordered]@{premerge_head=$pre;final_main=$final;remote_main=$remote;check='pass';tests='pass'} | ConvertTo-Json
